// The live class quiz draws on the lab's item bank. shared/class-platform/quiz-key.json (generated by
// tools/access-lab-index.mjs) lists which items qualify; the server uses the same file to judge answers.
let cached = null;

export function loadQuizKey(fetchImpl = (...a) => fetch(...a)) {
  if (!cached) {
    cached = fetchImpl("/shared/class-platform/quiz-key.json", { cache: "no-cache" })
      .then((r) => (r.ok ? r.json() : { items: {} }))
      .catch(() => ({ items: {} }));
    cached.then((k) => {
      if (!Object.keys(k.items).length) cached = null;
    });
  }
  return cached;
}

/** Quiz-eligible items in one domain/band as [{ id, band, domain, level }]. */
export const itemsFor = (key, { band, domain } = {}) =>
  Object.entries(key.items)
    .map(([id, v]) => ({ id, ...v }))
    .filter((v) => (!band || v.band === band) && (!domain || v.domain === domain));
